(() => {
  const data=window.SCHOOL_DATA, c=data.curriculum115;
  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const coreCards=()=>c.cores.map(core=>`<article class="course-core core-${core.code}"><span class="course-code">${core.code}</span><h3>${core.title}</h3><p>${esc(core.description)}</p><ul>${core.directions.map(d=>`<li><span>${d.code}</span>${d.title}</li>`).join('')}</ul></article>`).join('');
  const measures=()=>`<dl class="course-measures"><div><dt>三美</dt><dd>3<span>大核心</span></dd></div><div><dt>九向</dt><dd>9<span>個文化方向</span></dd></div><div><dt>四主題</dt><dd>4<span>條山海路徑</span></dd></div><div><dt>指標</dt><dd>45<span>項學習參照</span></dd></div></dl>`;
  const spiralSection=()=>{
    const s=c.spiral;
    return `<section class="course-section course-spiral" id="course-spiral"><p class="eyebrow">兩年共同規劃 / 每一次回訪，都多學一點</p><h2>再走回山海，帶著新的本領出發</h2><p class="course-lead">${esc(s.intro)}</p><div class="spiral-opening"><div><h3>時間在循環，學習在長大</h3><p>115上山林 → 115下海洋 → 116上山林 → 116下海洋。兩年共享文化核心，透過延續、延伸、互補、輪替與深化，讓孩子逐步累積能力。</p><p>低、中、高年段各有任務：體驗與覺察 → 技能與知識 → 探究與應用。各年段在兩年內持續加深，並依學生成長銜接下一個年段。</p><div class="spiral-skills">${['田調','族語','操作','協作','反思'].map(x=>`<span>${x}</span>`).join('')}</div></div><button class="photo-open" type="button" data-photo="plan115-spiral" data-caption="115・116共同規劃｜山林海洋循環與螺旋式課程" aria-label="放大兩年螺旋式課程圖"><img src="media/curriculum/115-116-spiral.png" alt="115上山林、115下海洋、116上山林、116下海洋，兩年任務持續深化" loading="lazy"><span>放大兩年學習路徑 ↗</span></button></div><div class="spiral-semesters">${s.semesters.map((x,i)=>`<article class="spiral-term ${x.place==='山林'?'forest':'ocean'}"><p class="eyebrow">0${i+1} / ${esc(x.term)} · ${esc(x.months)}</p><h3>${esc(x.place)}<span>${esc(x.label)}</span></h3><p>${esc(x.summary)}</p><dl>${x.units.map((items,j)=>`<div><dt>${esc(s.systems[j])}</dt><dd>${items.map(esc).join('、')}</dd></div>`).join('')}</dl></article>`).join('')}</div><p class="course-theme-note">${esc(s.moduleNote)}</p><h3 class="spiral-subheading">兩年之間，課程怎麼接起來？</h3><div class="doc-table-scroll"><table class="doc-table spiral-relations"><caption>115與116課程的承接關係</caption><thead><tr><th scope="col">115學年度</th><th scope="col">116學年度</th><th scope="col">連結方式</th><th scope="col">學習如何往前走</th></tr></thead><tbody>${s.relations.map(row=>`<tr>${row.map((cell,i)=>i===2?`<td><span class="spiral-relation">${esc(cell)}</span></td>`:`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h3 class="spiral-subheading">同一片山海，三種學習深度</h3><div class="course-progress-grid">${s.bands.map((b,i)=>`<article class="spiral-band"><p class="eyebrow">${esc(b.band)}</p><h3>${esc(c.progress[i].label)}</h3><dl><div><dt>115 · 累積經驗</dt><dd>${esc(b.year115)}</dd></div><div><dt>116 · 接續學習</dt><dd>${esc(b.year116)}</dd></div><div><dt>留下學習足跡</dt><dd>${esc(b.evidence)}</dd></div></dl></article>`).join('')}</div></section>`;
  };
  window.curriculumIntro=()=>`<section class="course-intro" aria-labelledby="course-intro-title"><div><p class="eyebrow">114課程基礎 · 115・116共同規劃</p><h2 id="course-intro-title">翻開山海課程地圖</h2><p>從114課程架構出發，看看115、116如何共同規劃。山林與海洋輪番登場，三美九向、四主題與45項指標串起兩年的螺旋式學習。</p><div class="detail-actions"><a class="button" href="resource.html?id=PLAN-016">114課程架構圖 →</a><a class="button primary" href="resource.html?id=PLAN-002#course-map">115・116螺旋式課程圖 →</a></div></div>${measures()}</section>`;
  window.renderCurriculum115=()=>{
    const ids=['PLAN-003','PLAN-006','PLAN-010'];
    const progresses=c.progress.map((p,i)=>{const r=data.resources.find(r=>r.id===ids[i]),a=data.assets[r?.cover];return `<article class="course-progress-card">${a?`<a href="resource.html?id=${r.id}" tabindex="-1" aria-hidden="true"><img src="${esc(a.src)}" alt="" loading="lazy"></a>`:''}<div><p class="eyebrow">0${i+1} / ${p.band}</p><h3>${p.label}</h3><strong>${p.identity}</strong><p>${esc(p.text)}</p>${a?`<a class="text-link" href="resource.html?id=${r.id}">看看114學年度的學習風景 →</a>`:''}</div></article>`;}).join('');
    const themes=c.themes.map((t,i)=>`<article class="course-theme"><p class="course-code">0${i+1}</p><h3>${t.title}</h3><p class="course-theme-subtitle">${esc(t.subtitle)}</p><ol>${t.steps.map((step,j)=>`<li><span>${c.progress[j].band}</span><p>${esc(step)}</p></li>`).join('')}</ol>${t.note?`<p class="course-theme-note">${esc(t.note)}</p>`:''}</article>`).join('');
    const directions=c.cores.map(core=>`<div class="course-indicator-core"><h3>${core.title} ${core.code}</h3>${core.directions.map(d=>`<details class="course-indicator"><summary><span>${d.code}</span>${d.title}<small>5 項</small></summary><ol>${d.items.map((item,i)=>`<li><span>${d.code}-${i+1}</span>${item}</li>`).join('')}</ol></details>`).join('')}</div>`).join('');
    return `<article class="page-body course-plan"><section class="course-hero"><p class="eyebrow">SALIMPO · 115・116學年度共同規劃</p><h2>把山海生活，<br>變成孩子的學習地圖。</h2><p>從部落日常出發，動手體驗、一起探究，再把發現分享出去。115、116學年度共同規劃，以「三美九向四主題」為文化核心，讓山林與海洋的學習跨年承接、螺旋深化。</p>${measures()}<div class="course-student-vision"><span>山海人文心</span><span>部落探究力</span><span>阿美國際眼</span></div></section><section class="course-section course-map-section year-course-map" id="course-map"><div><p class="eyebrow">115・116共同規劃 · 三美九向四主題</p><h2>把課程連成一張圖</h2><p>三美與九向承載文化內容，四主題串起學習任務；45項指標、低中高年段進程與兩年山林海洋循環，讓課程、教案與評量彼此連結。</p></div><button class="photo-open" type="button" data-photo="plan115-architecture" data-caption="115・116學年度｜三美九向、四主題、45項指標與螺旋式課程" aria-label="放大115・116螺旋式課程架構圖"><img src="media/curriculum/115-map.png" alt="115・116共同規劃架構：三美九向、四主題、45項課程指標、年段進程與兩年螺旋設計" loading="lazy"><span>放大課程地圖 ↗</span></button><div class="detail-actions"><a class="button" href="media/curriculum/115-map.png" target="_blank" rel="noopener noreferrer">開啟兩年架構高清大圖 ↗</a><a class="button" href="media/curriculum/115-map.png" download="115-116螺旋式課程架構圖.png">下載兩年架構 PNG</a><a class="button" href="media/curriculum/115-map.svg" download="115-116螺旋式課程架構圖.svg">下載可編輯SVG</a><a class="text-link" href="resource.html?id=PLAN-016">看看114課程架構 →</a></div></section><nav class="topic-nav course-jump" aria-label="課程架構章節"><a href="#course-map">兩年架構圖</a><a href="#course-spiral">螺旋式設計</a><a href="#course-core">三美九向</a><a href="#course-progress">年段進程</a><a href="#course-themes">四主題</a><a href="#course-indicators">45項指標</a><a href="#course-integration">跨領域整合</a><a href="reader.html?book=plan115&page=6">翻開計畫 ↗</a></nav>
    ${spiralSection()}<section class="course-section" id="course-core"><p class="eyebrow">01 / 三美，九個方向</p><h2>生活裡的美，就是課程的起點</h2><p class="course-lead">三個核心各有三個文化方向，讓孩子從生活、表達到部落關係，慢慢看見更完整的山海。</p><div class="course-core-grid">${coreCards()}</div></section>
    <section class="course-section" id="course-progress"><p class="eyebrow">02 / 從體驗到探究</p><h2>孩子長大，學習也跟著走深</h2><p class="course-lead">以五感打開學習，再練習合作與思考，讓學力和文化力一起成長。</p><div class="course-progress-grid">${progresses}</div></section>
    <section class="course-section" id="course-themes"><p class="eyebrow">03 / 四條山海路徑</p><h2>同一片山海，有好多種探索方式</h2><p class="course-lead">祭典、傳說、技藝與採集，依文化時序與場域條件串起九向。115、116共同安排，各年段透過深化、延伸、互補與輪替，展開不同的學習任務。</p><div class="course-theme-grid">${themes}</div></section>

    <section class="course-section" id="course-indicators"><p class="eyebrow">04 / 45項課程發展指標</p><h2>把學習的方向，看得更清楚</h2><p class="course-lead">九向各有五項指標（A-1-1至C-3-5），作為教案命名、學習目標、評量規準與成果蒐證的共同參照。點開一個方向，就能看到細項。</p><div class="course-indicator-grid">${directions}</div></section>
    <section class="course-section" id="course-integration"><p class="eyebrow">05 / 文化與學科一起學</p><h2>一個山海任務，打開跨領域的門</h2><p class="course-lead">文化課程全年規劃360–400節、每週8節以上，透過「三美九向」連結四大文化領域，並與部定課程整合。</p><div class="course-domain-grid">${c.domains.map(d=>`<article><h3>${d[0]}</h3><span>${d[1]}</span><p>${esc(d[2])}</p></article>`).join('')}</div><div class="doc-table-scroll"><table class="doc-table course-integration-table"><caption>115學年度文化課程與部定課程整合規劃</caption><thead><tr><th scope="col">年段</th><th scope="col">文化課程單元</th><th scope="col">主要整合領域</th><th scope="col">約略節數</th></tr></thead><tbody>${c.integrations.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="course-theme-note">節數為115學年度規劃概數，依課程發展會議、教學情形與部落回饋調整。</p></section>
    ${window.partnershipCallout?.()||''}<section class="course-next"><div><p class="eyebrow">接著，走進課堂</p><h2>看懂架構，再看看孩子怎麼學</h2><p>翻開115計畫的完整圖文，或走進教案書屋，閱讀114學年度的31個主題單元。</p></div><div class="detail-actions"><a class="button primary" href="reader.html?book=plan115&page=1">閱讀115完整計畫 · 40頁 ↗</a><a class="button" href="lessons.html">走進教案書屋 →</a><a class="text-link" href="learning.html">逛逛山海探索站 →</a></div></section></article>`;
  };
})();
